"use client";

import { useState } from "react";
import { CheckCircle, AlertCircle, Search } from "lucide-react";

export default function TabelVerifikasi({ initialData }: { initialData: any[] }) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Logika pilih semua dan eksekusi verifikasi massal di sini...

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
      <div className="p-8 border-b border-slate-50 flex justify-between items-center">
        <h2 className="text-lg font-bold text-slate-800">Antrean Verifikasi</h2>
        <button 
          className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100 disabled:bg-slate-200"
          disabled={selectedIds.length === 0}
        >
          Verifikasi ({selectedIds.length}) Data Terpilih
        </button>
      </div>
      
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50/50">
            <tr>
              <th className="p-4"><input type="checkbox" className="rounded border-slate-300" /></th>
              <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Tanggal</th>
              <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Unit</th>
              <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Nama Pasien</th>
              <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Temuan HAIs</th>
              <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {initialData.map((row) => (
              <tr key={row.id} className="hover:bg-slate-50/50 transition-colors">
                {/* Render baris data perawat di sini */}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}